<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Verificación de constancia · AIDEX</title><link rel="icon" type="image/svg+xml" href="/assets/brand/logo-v.svg"><link rel="stylesheet" href="/assets/vendor/bootstrap/bootstrap.min.css"><link rel="stylesheet" href="/assets/app.css"></head><body class="auth-body"><main class="container py-5"><section class="panel form-panel"><img src="/assets/brand/logo-h.svg" alt="AIDEX" width="360"><h1 class="mt-4">Verificación de constancia</h1>
